function validate(input) {
  const [{ Steps = [] }] = input;
  const seen = new Set();
  for (const [user, count, date] of Steps) {
    if (user === null || count === null || date === null) return 'user_id, steps_count and steps_date cannot be null.';
    if (count < 0) return 'steps_count cannot be negative.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || new Date(`${date}T00:00:00Z`).toISOString().slice(0, 10) !== date) return `${date} is not a valid date.`;
    const key = `${user}|${date}`;
    if (seen.has(key)) return `User ${user} has two rows on ${date}.`;
    seen.add(key);
  }
  return null;
}

