function generate(rand, size) {
  const day = (base, offset) => new Date(Date.parse(`${base}T00:00:00Z`) + offset * 86400000).toISOString().slice(0, 10);
  const Steps = [];
  if (size === 'small') {
    // A few users, each with a random subset of an 8-day span that may cross a month, year or leap-day boundary.
    const base = ['2021-09-01', '2021-08-28', '2020-02-26', '2021-12-29', '2021-02-25'][Math.floor(rand() * 5)];
    const users = 1 + Math.floor(rand() * 3);
    for (let user = 1; user <= users; user++) {
      for (let offset = 0; offset < 8; offset++) {
        if (Steps.length < 8 && rand() < 0.6) Steps.push([user, Math.floor(rand() * 1000), day(base, offset)]);
      }
    }
    // Shuffle so rows are not listed in date order.
    for (let i = Steps.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Steps[i], Steps[j]] = [Steps[j], Steps[i]]; }
  } else {
    for (let user = 1; Steps.length < 2000; user++) {
      for (let offset = 0; offset < 130 && Steps.length < 2000; offset++) {
        if (rand() < 0.75) Steps.push([user, Math.floor(rand() * 20000), day('2021-11-15', offset)]);
      }
    }
  }
  return [{ Steps }];
}
